import {Catalog} from 'react-planner';

let catalog = new Catalog();

import * as Areas from './areas/**/planner-element.jsx';
import * as Lines from './lines/**/planner-element.jsx';
import * as Holes from './holes/**/planner-element.jsx';
import * as Items from './items/**/planner-element.jsx';

for( let x in Areas ) catalog.registerElement( Areas[x] );
for( let x in Lines ) catalog.registerElement( Lines[x] );
for( let x in Holes ) catalog.registerElement( Holes[x] );
for( let x in Items ) catalog.registerElement( Items[x] );

// ========================================
// TEXTE ET ANNOTATIONS
// ========================================
catalog.registerCategory('text', '📝 Texte & Surface', [
  Items.text3d         // Texte avec calcul de surface automatique
]);

// ========================================
// CATÉGORIES PRIORITAIRES (Croquis rapide)
// ========================================

// Séjour - Living Room
catalog.registerCategory('living-room', '🛋️ Séjour', [
  Items.sofa,           // Canapé
  Items.table,          // Table basse
  Items.canteenTable,   // Table à manger
  Items.chair,          // Chaises
  Items.armchairs,      // Fauteuils
  Items.tv,             // TV
  Items.bookcase        // Bibliothèque
]);

// Chambre - Bedroom
catalog.registerCategory('bedroom', '🛏️ Chambre', [
  Items.bedDouble,      // Lit 2 places
  Items.bedSingle,      // Lit 1 place
  Items.wardrobe,       // Armoire
  Items.desk,           // Bureau simple
  Items.chair           // Chaise
]);

// Cuisine - Kitchen
catalog.registerCategory('kitchen', '🍳 Cuisine', [
  Items.kitchen,        // Plan de travail avec évier + cuisinière
  Items.fridge,         // Réfrigérateur
  Items.sink,           // Évier supplémentaire
  Items.table,          // Table
  Items.chair           // Chaise
]);

// Salle de bain - Bathroom
catalog.registerCategory('bathroom', '🚿 Salle de bain', [
  Items.shower,         // Douche
  Items.sink,           // Lavabo
  Items.toilet          // Toilette/WC
]);

// Bureau - Office
catalog.registerCategory('office', '💼 Bureau', [
  Items.deskoffice,     // Bureau professionnel
  Items.desk,           // Table bureau simple
  Items.chair,          // Chaise
  Items.bookcase,       // Bibliothèque
  Items.monitorPc       // Ordinateur
]);

// ========================================
// OUVERTURES
// ========================================

// Portes - Doors
catalog.registerCategory('doors', '🚪 Portes', [
  Holes.door,           // Porte simple
  Holes.doorDouble,     // Porte double
  Holes.slidingDoor     // Porte coulissante
]);

// Fenêtres - Windows
catalog.registerCategory('windows', '🪟 Fenêtres', [
  Holes.window,                // Fenêtre simple
  Holes.sashWindow,           // Fenêtre à guillotine
  Holes.windowCurtain         // Fenêtre avec rideaux
]);

// ========================================
// AUTRES ÉLÉMENTS UTILES
// ========================================

// Éléments structurels
catalog.registerCategory('structural', '🏗️ Structure', [
  Items.column,         // Colonne ronde
  Items.columnSquare,   // Colonne carrée
  Items.balcony         // Balcon
]);

// Équipements techniques (optionnel - moins prioritaire)
catalog.registerCategory('equipment', '⚙️ Équipements', [
  Items.radiatorModernStyle,  // Radiateur moderne
  Items.radiatorOldStyle,     // Radiateur ancien
  Items.airConditioner,       // Climatisation
  Items.smokeDetector,        // Détecteur de fumée
  Items.fireExtinguisher      // Extincteur
]);

// Note: Les autres éléments moins utilisés restent disponibles via la recherche

export default catalog;
