import * as Three from 'three';
import React from 'react';

// Toilet materials
const ceramicMaterial = new Three.MeshPhongMaterial({ color: 0xFFFFFF });
const seatMaterial = new Three.MeshLambertMaterial({ color: 0xF5F5F5 });
const waterMaterial = new Three.MeshPhongMaterial({
  color: 0xADD8E6,
  transparent: true,
  opacity: 0.6
});

function makeObjectMaxLOD() {
  let toilet = new Three.Mesh();

  // Toilet bowl base
  let base = new Three.Mesh(
    new Three.CylinderGeometry(18, 20, 15, 16),
    ceramicMaterial
  );
  base.position.y = 7.5;
  toilet.add(base);

  // Toilet bowl top
  let bowl = new Three.Mesh(
    new Three.CylinderGeometry(16, 18, 20, 16),
    ceramicMaterial
  );
  bowl.position.y = 25;
  toilet.add(bowl);

  // Toilet seat
  let seat = new Three.Mesh(
    new Three.TorusGeometry(16, 3, 8, 16),
    seatMaterial
  );
  seat.position.y = 36;
  seat.rotation.x = Math.PI / 2;
  toilet.add(seat);

  // Water tank
  let tank = new Three.Mesh(
    new Three.BoxGeometry(32, 40, 15),
    ceramicMaterial
  );
  tank.position.y = 50;
  tank.position.z = -12;
  toilet.add(tank);

  // Tank lid
  let lid = new Three.Mesh(
    new Three.BoxGeometry(32, 3, 15),
    ceramicMaterial
  );
  lid.position.y = 71.5;
  lid.position.z = -12;
  toilet.add(lid);

  // Flush button
  let button = new Three.Mesh(
    new Three.CylinderGeometry(3, 3, 2, 16),
    seatMaterial
  );
  button.position.y = 73;
  button.position.z = -12;
  toilet.add(button);

  return toilet;
}

function makeObjectMinLOD() {
  let toilet = new Three.Mesh();

  // Simplified toilet - just basic shapes
  let bowl = new Three.Mesh(
    new Three.CylinderGeometry(16, 20, 35, 12),
    ceramicMaterial
  );
  bowl.position.y = 17.5;
  toilet.add(bowl);

  let tank = new Three.Mesh(
    new Three.BoxGeometry(32, 40, 15),
    ceramicMaterial
  );
  tank.position.y = 50;
  tank.position.z = -12;
  toilet.add(tank);

  return toilet;
}

export default {
  name: 'toilette',
  prototype: 'items',

  info: {
    tag: ['salle de bain', 'sanitaire'],
    title: 'Toilette',
    description: 'WC avec réservoir',
    image: require('./toilet.png')
  },

  properties: {
    altitude: {
      label: 'altitude',
      type: 'length-measure',
      defaultValue: {
        length: 0,
        unit: 'cm'
      }
    }
  },

  render2D: function (element, layer, scene) {
    const WIDTH = 40;
    const DEPTH = 60;
    let angle = element.rotation + 90;

    let textRotation = 0;
    if (Math.sin(angle * Math.PI / 180) < 0) {
      textRotation = 180;
    }

    return (
      <g transform={`translate(${-WIDTH / 2},${-DEPTH / 2})`}>
        {/* Tank */}
        <rect key="1" x={WIDTH * 0.1} y={DEPTH * 0.05} width={WIDTH * 0.8} height={DEPTH * 0.4}
          style={{stroke: element.selected ? '#0096fd' : 'none', strokeWidth: element.selected ? "2px" : "0", fill: "#FFF"}}/>
        {/* Bowl */}
        <ellipse key="2" cx={WIDTH / 2} cy={DEPTH * 0.7} rx={WIDTH * 0.4} ry={DEPTH * 0.25}
          style={{stroke: element.selected ? '#0096fd' : 'none', strokeWidth: element.selected ? "2px" : "0", fill: "#FFF"}}/>
        <text key="3" x="0" y="0"
          transform={`translate(${WIDTH / 2}, ${DEPTH / 2}) scale(1,-1) rotate(${textRotation})`}
          style={{textAnchor: "middle", fontSize: "11px"}}>
          WC
        </text>
      </g>
    )
  },

  render3D: function (element, layer, scene) {
    let newAltitude = element.properties.get('altitude').get('length');

    /********** lod max ************/
    let toiletMaxLOD = new Three.Object3D();
    let objectMaxLod = makeObjectMaxLOD();
    toiletMaxLOD.add(objectMaxLod.clone());
    toiletMaxLOD.position.y += newAltitude;

    /********** lod min ************/
    let toiletMinLOD = new Three.Object3D();
    let objectMinLod = makeObjectMinLOD();
    toiletMinLOD.add(objectMinLod.clone());
    toiletMinLOD.position.y += newAltitude;

    /**** all level of detail ***/
    let lod = new Three.LOD();
    lod.addLevel(toiletMaxLOD, 200);
    lod.addLevel(toiletMinLOD, 900);
    lod.updateMatrix();
    lod.matrixAutoUpdate = false;

    if (element.selected) {
      let bbox = new Three.BoxHelper(lod, 0x99c3fb);
      bbox.material.linewidth = 5;
      bbox.renderOrder = 1000;
      bbox.material.depthTest = false;
      lod.add(bbox);
    }

    return Promise.resolve(lod);
  }
};
